          &lt;i class=&quot;feather icon-arrow-left&quot;&gt;&lt;/i&gt; Back to Dashboard
        &lt;/a&gt;
        &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary ladda-button&quot; data-style=&quot;expand-right&quot; id=&quot;save_sig_btn&quot;&gt;
